function Countdown({ compact = false }: { compact?: boolean }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => { const timer = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, []);
  const target = new Date('2025-10-18T20:00:00').getTime();
  const distance = Math.max(0, target - now);
  const values = [
    { label: 'يوم', value: Math.floor(distance / 86400000) },
    { label: 'ساعة', value: Math.floor(distance / 3600000) % 24 },
    { label: 'دقيقة', value: Math.floor(distance / 60000) % 60 },
    { label: 'ثانية', value: Math.floor(distance / 1000) % 60 },
  ];
  return <div className={`flex ${compact ? 'gap-2' : 'gap-3'} justify-center`} dir="rtl">
    {values.map(item => <div key={item.label} className={`${compact ? 'min-w-[49px] px-1.5 py-2' : 'min-w-[62px] px-2 py-3'} rounded-xl bg-[#f3eadb] text-center`} data-testid={`countdown-${item.label}`}>
      <div className={`${compact ? 'text-lg' : 'text-2xl'} font-bold text-[#183d37] tabular-nums`}>{String(item.value).padStart(2, '0')}</div><div className="mt-0.5 text-[10px] text-[#70827d]">{item.label}</div>
    </div>)}
  </div>;
}

